//attachment maker
//here is the ui code
function attachment_ui()
{
	var checkExist = ActiveSceneRoot.Properties("AttachmentTool");
	if(checkExist)
	{
		logmessage("found");
		DeleteObj(checkExist);
	} 
	
		//create ppg	
		var oPpg = ActiveSceneRoot.AddProperty("CustomProperty",false,"AttachmentTool");
		var layout = oPpg.PPGLayout;
		
			layout.AddRow();
				layout.AddButton("AddAttachment");		
				layout.AddButton("ExportQCcode");
			layout.EndRow();
		
		layout.Logic =  AddAttachment_OnClicked.toString() +
									  ExportQCcode_OnClicked.toString();
						
		layout.Language = "JScript";
		InspectObj(oPpg, null, null, 3 );
} 



function AddAttachment_OnClicked()
{
		num_sel = selection.count;
		if (num_sel == 0)
		{
			logmessage ("Nothing Selected", siFatal);
			return;
		}
		
	//make a collecton of all the items
	selected_items = new ActiveXObject("XSI.Collection");
	for (x = 0; x < num_sel;x++)
		{
			selected_items.AddItems(selection(x));
		}
	//add a null to each selected object
	for (i = 0; i < selected_items.count;i++)
	{
		logmessage (selected_items(i));
		obj = selected_items(i);
		logmessage (obj);
		parent_name = new String(obj);
		//strip away the model name from the attachment name
		model = obj.model;
		Bip = "Bip01";
		//get rid of the model name
		parent_split = parent_name.split(model);
		//see if Bip01 is in the name and get rid of that as well (search returns -1 if there is no match)
		//if model == "Scene Root" then it has no model prefix and we don't do anything
		//this mess of if/else stuff is to get through XSI's name space issues	
		if (model == "Scene_Root")
		{
			check = -1;
		}
		else
		{
			check = parent_split[1].search(Bip);
		}	
		if (check != -1)
			{
			bip_split = parent_split[1].split(Bip);
			null_name = "attach" + bip_split[1];
			}
		else
			{
					if (model == "Scene_Root")
					{
					null_name = "attach_" + parent_name;
					}
					else
					{
					null_name = "attach" + parent_split[1];
					}
			}
		
		GetPrim("Null", null_name);
		//because XSI can append a 1 to the object if a duplicate exists (and we need to allow one to)
		//we need to catch the name of the null post creation
		attach_name = GetValue("SelectionList");
		parent_fixed = parent_name.toString();
		//XSI does not always return strings so for the parent name we need to force it to use a string
		//stick the null to the selected object
		MatchTransform (attach_name, parent_fixed, siSRT, null);
		//parent it to the object
		ParentObj (parent_fixed, attach_name);
	}
	
	//make an attachment layer if it does not exist, and add all the atttachments to it
	layer = Dictionary.GetObject("Layers.Attachments", false);
	if (!layer)
		{
		CreateLayer ("Default_New_Layer","Attachments");
		}
			SelectObj ("*attach*");
			MoveToLayer("Layers.Attachments");
			DeselectAll();
}


function ExportQCcode_OnClicked()
{

	attachments = new ActiveXObject("XSI.Collection");
	attachments.Items = ("*attach_*");
		if (!attachments.Items)
		{
			logmessage ("No Attachment Points", siFatal);
			return;
		}
	quote = '"';
   var fso, tf;
   fso = new ActiveXObject("Scripting.FileSystemObject");
   tf = fso.CreateTextFile("c:\\attachmentqccode.txt", true);
   tf.WriteLine("//attachment points") ;
   for (i=0; i < attachments.count; i++)
   {
   // Get all the values and spit out the qc code
   //this is the attachment template code
   //$attachment (name) (bone name) (X) (Y) (Z) ["absolute"] ["rigid"] ["rotate" pitch yaw roll] 
   

   px = (attachments(i).posx.Value);
   py = (attachments(i).posy.Value);
   pz = (attachments(i).posz.Value);

		posx = px.toFixed(4);
		posy = py.toFixed(4);
		posz = pz.toFixed(4);

//XSI and modelviewer have their axis messed up so.....
//make x equal y and y = z and z = y 
   rx = (attachments(i).roty.Value);
   ry = (attachments(i).rotz.Value);
   rz = (attachments(i).rotx.Value);
   
   	rotx = rx.toFixed(4);
	roty = ry.toFixed(4);
	rotz = rz.toFixed(4);
	
		//split off the model name
   	dot = ".";
  	attach_name = attachments(i).name;
   	bone = attachments(i).parent.name;
   	prefix = attachments(i).model;

   //qcline = ("$attachment" + "\t" + quote + attachments(i) + quote + "\t" + quote + bone + quote + "\t" + posx + "\t" + posy + "\t" + posz + "\t" + quote + "absolute" + quote + "\t" + quote + "rigid" + quote + "\t" + quote + "rotate" + quote + "\t" + rotx + "\t" + roty + "\t" + rotz);
   	qcline = ("$attachment" + "\t" + quote + attach_name + quote + "\t" + quote + prefix + "." + bone + quote + "\t" + posx + "\t" + posy + "\t" + posz + "\t" + quote + "rotate" + quote + "\t" + rotx + "\t" + roty + "\t" + rotz);
		tf.WriteLine(qcline) ;
  }
   tf.Close();
  var objShell = new ActiveXObject("WScript.Shell"); 
  objShell.Run("c:\\attachmentqccode.txt");
}